macro_rules! IOMMU_WAIT_OP {
($iommu:expr, $offset:expr, $cond:expr, $sts:expr) => {
loop {
let start_time: u64 = get_cycles();
while true {
$sts = readl(((unsafe { ((*$iommu).reg as *const u8).wrapping_offset(($offset) as isize) }) as *mut ()) as *const ());
if $cond {
break;
}
if ((unsafe { tsc_khz }) as u64).wrapping_mul(10).wrapping_mul(1000) < get_cycles().wrapping_sub(start_time) {
unsafe { panic(c"DMAR hardware is malfunctioning\n".as_ptr() as *const u8) };
unsafe { core::hint::unreachable_unchecked() };
}
cpu_relax();
}
if true {
break;
}
}
};
}

